import {AgentAvatar} from '../../AgentAvatar'
import {MarkdownRenderer} from '@github-ui/copilot-markdown'
import {LoadingSkeleton} from '@github-ui/skeleton/LoadingSkeleton'
import {clsx} from 'clsx'
import styles from './LegacyCopilotMessage.module.css'

interface CopilotMessageBubbleProps {
  markdown: string
  showAvatar?: boolean
}

export function CopilotMessageBubble({markdown, showAvatar = true}: CopilotMessageBubbleProps) {
  return (
    <div className={styles.message}>
      <div className={styles.icon}>
        {showAvatar && <AgentAvatar size={32} animationType="static" loopAnimation={false} />}
      </div>
      <MarkdownRenderer className={styles.text} markdown={markdown} />
    </div>
  )
}

export function CopilotMessageContainer({children}: {children: React.ReactNode}) {
  return <div className={styles.container}>{children}</div>
}

export function CopilotMessageLoading() {
  return (
    <div className={styles.container}>
      <div className={styles.message}>
        <div className={styles.icon}>
          <LoadingSkeleton variant="elliptical" height="32px" width="32px" />
        </div>
        <div className={clsx(styles.text, styles.loadingText)}>
          <LoadingSkeleton variant="rounded" height="sm" width="100%" />
          <LoadingSkeleton variant="rounded" height="sm" width="100%" />
          <LoadingSkeleton variant="rounded" height="sm" width="70%" />
        </div>
      </div>
    </div>
  )
}
