import {generateSSOUrl} from '@github-ui/global-sso-banner/generate-sso-url'
import {useLocation} from '@github-ui/react-router'
import {AlertIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Flash} from '@primer/react'

import type {CopilotChatOrg} from '../../utils/copilot-chat-types'
import styles from './SSOWarningBanner.module.css'

export function SSOWarningBanner({ssoOrganizations}: {ssoOrganizations: CopilotChatOrg[]}) {
  const location = useLocation()

  if (ssoOrganizations.length === 0) {
    return null
  }

  return (
    <Flash className={styles.ssoWarningBanner} variant="warning">
      <AlertIcon size={16} />
      <span>
        Some threads are hidden. Please{' '}
        {ssoOrganizations.length === 1 ? (
          ssoOrganizations[0]?.login ? (
            <a href={generateSSOUrl(ssoOrganizations[0].login, location)}>sign in</a>
          ) : (
            <span>sign in</span>
          )
        ) : (
          <ActionMenu>
            <ActionMenu.Anchor>
              <button type="button" className={styles.ssoSignInLink}>
                sign in
              </button>
            </ActionMenu.Anchor>
            <ActionMenu.Overlay>
              <ActionList>
                {ssoOrganizations
                  .filter(org => org.login)
                  .map(org => (
                    <ActionList.LinkItem key={org.login} href={generateSSOUrl(org.login, location)}>
                      {org.login}
                    </ActionList.LinkItem>
                  ))}
              </ActionList>
            </ActionMenu.Overlay>
          </ActionMenu>
        )}{' '}
        <span>with SSO to view them.</span>
      </span>
    </Flash>
  )
}
