import {isPendingSession, type Session} from '../../../types/session'
import type {PublicUser} from '../../../types/public-user'
import {ExpandableMarkdown} from '../../expandable-markdown/ExpandableMarkdown'
import styles from './UserProblemStatementMessage.module.css'
import {useAgentInfo} from '../../../hooks/use-agent-info'
import {createMarkdownWithAgentLinks} from '../../../utils/markdown-link-utils'
import {useCurrentUser} from '../../../contexts/CurrentUserContext'
import {UserMessageLoading} from './UserMessageLoading'
import {UserMessageLayout} from './UserMessageLayout'
import {useIntentDetection} from '../../../hooks/useIntentDetection'

interface UserProblemStatementMessageProps {
  session: Session
  sessionOwner?: PublicUser
  isLoading?: boolean
}

const ErrorMessage = () => (
  <UserMessageLayout>
    <p className={styles.messageText}>Failed to fetch problem statement</p>
  </UserMessageLayout>
)

export const UserProblemStatementMessage = ({
  session,
  sessionOwner,
  isLoading = false,
}: UserProblemStatementMessageProps) => {
  const {data: agentInfo} = useAgentInfo(session.agent_id)
  const {currentUser} = useCurrentUser()

  // Suppress the "You asked" tags when we're doing intent detection and/or chatting
  const isPending = isPendingSession(session)
  const {isChatSession, isUsingIntentDetection} = useIntentDetection(session)

  if (!session.event_content) {
    return isLoading ? <UserMessageLoading /> : <ErrorMessage />
  }

  const getAuthorDisplayLogin = () => {
    if (currentUser && session.user_id === currentUser.id) {
      return 'You'
    }

    return sessionOwner?.login ?? 'User'
  }

  const avatarUrl =
    sessionOwner?.primaryAvatarUrl ?? `https://avatars.githubusercontent.com/${sessionOwner?.login ?? 'ghost'}`

  // Process markdown with agent links if needed
  const markdownContent = agentInfo
    ? createMarkdownWithAgentLinks(session.event_content ?? '', agentInfo)
    : (session.event_content ?? '')

  return (
    <UserMessageLayout avatarUrl={avatarUrl}>
      {!(isChatSession || (isUsingIntentDetection && isPending)) && (
        <span className={styles.messageMeta}>{getAuthorDisplayLogin()} asked</span>
      )}
      <ExpandableMarkdown className={styles.messageText} markdown={markdownContent} />
    </UserMessageLayout>
  )
}
