import {useCallback} from 'react'

type UseScrollToBottomOptions = {
  // container element to scroll or use null/undefined for window/viewport scrolling
  containerRef?: React.RefObject<HTMLElement | null>
  behavior?: ScrollBehavior
  // threshold in pixels - if scroll distance is greater than this, use smooth behavior when 'auto' is specified
  smoothThreshold?: number
}

const getScrollParams = (container?: HTMLElement | null) => {
  if (!container) {
    const docEl = document.scrollingElement || document.documentElement
    const currentTop = window.scrollY || window.pageYOffset
    const targetTop = docEl.scrollHeight
    return {
      element: null,
      targetTop,
      distance: Math.abs(targetTop - currentTop),
    }
  }
  return {
    element: container,
    targetTop: container.scrollHeight,
    distance: Math.abs(container.scrollHeight - container.scrollTop),
  }
}

type ScrollToBottomOptions = {
  behavior?: ScrollBehavior
  offset?: number
}

export function useScrollToBottom({
  containerRef,
  behavior: defaultBehavior = 'auto',
  smoothThreshold,
}: UseScrollToBottomOptions) {
  const scrollToBottom = useCallback(
    (options?: ScrollToBottomOptions) => {
      const {distance, element, targetTop} = getScrollParams(containerRef?.current)

      const behavior = options?.behavior ?? defaultBehavior
      const offset = options?.offset ?? 0

      // Determine actual behavior based on threshold if 'auto' is specified
      let actualBehavior = behavior
      if (behavior === 'auto' && smoothThreshold !== undefined) {
        actualBehavior = distance >= smoothThreshold ? 'smooth' : 'auto'
      }

      const adjustedTop = targetTop - offset

      if (!element) {
        window.scrollTo({top: adjustedTop, behavior: actualBehavior})
      } else {
        element.scrollTo({top: adjustedTop, behavior: actualBehavior})
      }
    },
    [containerRef, defaultBehavior, smoothThreshold],
  )

  return {scrollToBottom} as const
}
