import {useCallback, useState} from 'react'
import {ChevronUpIcon, DashIcon, ScreenFullIcon} from '@primer/octicons-react'
import {IconButton} from '@primer/react'
import type {NormalizedPrompt} from '../../components/session-logs/prompt-log-utils'
import type {
  AskUserArguments,
  SimpleAskUserArguments,
  ElicitationAskUserArguments,
  CommandType,
  ExitPlanModeArguments,
  PermissionRequestArguments,
} from '../../types/session'
import {isElicitationAskUser} from '../../types/session'
import {COMMAND_TYPES} from '../../constants/command-types'
import {SimpleAskUserDisplay} from '../session-logs/SimpleAskUserDisplay'
import {ElicitationAskUserDisplay} from '../session-logs/ElicitationAskUserDisplay'
import {PermissionDisplay} from '../session-logs/PermissionDisplay'
import {PlanApprovalDisplay} from '../session-logs/PlanApprovalDisplay'
import styles from './PromptInput.module.css'

interface PromptInputProps {
  /** The pending prompt to render */
  prompt: NormalizedPrompt
  /** Callback when user responds to the prompt, including the command type for the response */
  onRespond?: (toolCallId: string, response: unknown, commandType: CommandType) => void
  /** Callback to dismiss/skip the prompt */
  onDismiss?: () => void
}

const PROMPT_TITLES: Record<string, string> = {
  ask_user: 'Question from agent',
  permission_request: 'Permission requested',
  exit_plan_mode: 'Plan ready for review',
}

/**
 * Renders a CLI prompt (ask_user, permission_request, exit_plan_mode) in the chat input area.
 * Wraps the existing display components and handles response callbacks.
 */
export function PromptInput({prompt, onRespond, onDismiss}: PromptInputProps) {
  const [isExpanded, setIsExpanded] = useState(true)
  const [planDialogOpen, setPlanDialogOpen] = useState(false)
  const [hasResponded, setHasResponded] = useState(false)
  const {toolName, toolCallId, arguments: args} = prompt

  const title = PROMPT_TITLES[toolName] ?? 'Agent prompt'
  const isPlanPrompt = toolName === 'exit_plan_mode'

  const handleRespond = useCallback(
    (id: string, response: unknown, commandType: CommandType) => {
      if (hasResponded) return
      setHasResponded(true)
      onRespond?.(id, response, commandType)
    },
    [hasResponded, onRespond],
  )

  // Wrap onDismiss similarly
  const handleDismiss = useCallback(() => {
    if (hasResponded) return
    setHasResponded(true)
    onDismiss?.()
  }, [hasResponded, onDismiss])

  const renderContent = () => {
    switch (toolName) {
      case 'ask_user':
        return (
          <AskUserPromptContent
            args={args as AskUserArguments}
            toolCallId={toolCallId}
            onRespond={handleRespond}
            onDismiss={handleDismiss}
            disabled={hasResponded}
          />
        )
      case 'permission_request':
        return (
          <PermissionPromptContent
            args={args as PermissionRequestArguments}
            toolCallId={toolCallId}
            onRespond={handleRespond}
            disabled={hasResponded}
          />
        )
      case 'exit_plan_mode':
        return (
          <PlanApprovalPromptContent
            args={args as ExitPlanModeArguments}
            toolCallId={toolCallId}
            onRespond={handleRespond}
            dialogOpen={planDialogOpen}
            onDialogClose={() => setPlanDialogOpen(false)}
            disabled={hasResponded}
          />
        )
      default:
        return null
    }
  }

  return (
    <div className={styles.container}>
      <div className={styles.header}>
        <span className={styles.headerTitle}>{title}</span>
        <div className={styles.headerActions}>
          {isPlanPrompt && (
            <IconButton
              icon={ScreenFullIcon}
              aria-label="View full plan"
              size="small"
              variant="invisible"
              onClick={() => setPlanDialogOpen(true)}
            />
          )}
          <IconButton
            icon={isExpanded ? DashIcon : ChevronUpIcon}
            aria-label={isExpanded ? 'Minimize' : 'Expand'}
            size="small"
            variant="invisible"
            onClick={() => setIsExpanded(!isExpanded)}
          />
        </div>
      </div>
      <div className={styles.contentWrapper} data-expanded={isExpanded}>
        <div className={styles.content}>{renderContent()}</div>
      </div>
    </div>
  )
}

interface AskUserPromptContentProps {
  args: AskUserArguments
  toolCallId: string
  onRespond?: (toolCallId: string, response: unknown, commandType: CommandType) => void
  onDismiss?: () => void
  disabled?: boolean
}

function AskUserPromptContent({args, toolCallId, onRespond, onDismiss, disabled}: AskUserPromptContentProps) {
  if (isElicitationAskUser(args)) {
    return (
      <ElicitationAskUserPromptContent args={args} toolCallId={toolCallId} onRespond={onRespond} disabled={disabled} />
    )
  }

  return (
    <SimpleAskUserPromptContent
      args={args}
      toolCallId={toolCallId}
      onRespond={onRespond}
      onDismiss={onDismiss}
      disabled={disabled}
    />
  )
}

interface SimpleAskUserPromptContentProps {
  args: SimpleAskUserArguments
  toolCallId: string
  onRespond?: (toolCallId: string, response: unknown, commandType: CommandType) => void
  onDismiss?: () => void
  disabled?: boolean
}

function SimpleAskUserPromptContent({
  args,
  toolCallId,
  onRespond,
  onDismiss,
  disabled,
}: SimpleAskUserPromptContentProps) {
  const handleChoose = useCallback(
    (choice: string) => {
      onRespond?.(
        toolCallId,
        {promptId: toolCallId, answer: choice, wasFreeform: false},
        COMMAND_TYPES.ASK_USER_RESPONSE,
      )
    },
    [toolCallId, onRespond],
  )

  const handleFreeform = useCallback(
    (text: string) => {
      onRespond?.(toolCallId, {promptId: toolCallId, answer: text, wasFreeform: true}, COMMAND_TYPES.ASK_USER_RESPONSE)
    },
    [toolCallId, onRespond],
  )

  return (
    <SimpleAskUserDisplay
      question={args.question}
      choices={'choices' in args && args.choices ? args.choices : []}
      multiSelect={false}
      allowFreeform={args.allowFreeform ?? true}
      onChoose={handleChoose}
      onFreeform={handleFreeform}
      onSkip={onDismiss}
      disabled={disabled ?? false}
    />
  )
}

interface ElicitationAskUserPromptContentProps {
  args: ElicitationAskUserArguments
  toolCallId: string
  onRespond?: (toolCallId: string, response: unknown, commandType: CommandType) => void
  disabled?: boolean
}

function ElicitationAskUserPromptContent({
  args,
  toolCallId,
  onRespond,
  disabled,
}: ElicitationAskUserPromptContentProps) {
  const handleElicitationSubmit = useCallback(
    (content: Record<string, string | string[]>) => {
      onRespond?.(toolCallId, {promptId: toolCallId, action: 'accept', content}, COMMAND_TYPES.ELICITATION_RESPONSE)
    },
    [toolCallId, onRespond],
  )

  const handleDecline = useCallback(() => {
    onRespond?.(toolCallId, {promptId: toolCallId, action: 'decline'}, COMMAND_TYPES.ELICITATION_RESPONSE)
  }, [toolCallId, onRespond])

  return (
    <ElicitationAskUserDisplay
      message={args.message}
      schema={args.requestedSchema}
      onElicitationSubmit={handleElicitationSubmit}
      onDecline={handleDecline}
      disabled={disabled ?? false}
    />
  )
}

interface PermissionPromptContentProps {
  args: PermissionRequestArguments
  toolCallId: string
  onRespond?: (toolCallId: string, response: unknown, commandType: CommandType) => void
  disabled?: boolean
}

function PermissionPromptContent({args, toolCallId, onRespond, disabled}: PermissionPromptContentProps) {
  const {kind, toolName, description, command, filePath} = args

  const handleRespond = useCallback(
    (approved: boolean, scope?: 'once' | 'session') => {
      onRespond?.(
        toolCallId,
        {promptId: toolCallId, approved, scope: scope ?? 'once'},
        COMMAND_TYPES.PERMISSION_RESPONSE,
      )
    },
    [toolCallId, onRespond],
  )

  const detail = command || filePath

  return (
    <PermissionDisplay
      kind={kind}
      toolName={toolName}
      intention={description}
      detail={detail}
      onRespond={handleRespond}
      disabled={disabled}
    />
  )
}

interface PlanApprovalPromptContentProps {
  args: ExitPlanModeArguments
  toolCallId: string
  onRespond?: (toolCallId: string, response: unknown, commandType: CommandType) => void
  dialogOpen: boolean
  onDialogClose: () => void
  disabled?: boolean
}

function PlanApprovalPromptContent({
  args,
  toolCallId,
  onRespond,
  dialogOpen,
  onDialogClose,
  disabled,
}: PlanApprovalPromptContentProps) {
  const {summary, actions = [], recommendedAction} = args

  const handleAction = useCallback(
    (action: string) => {
      onRespond?.(
        toolCallId,
        {promptId: toolCallId, approved: true, selectedAction: action},
        COMMAND_TYPES.PLAN_APPROVAL_RESPONSE,
      )
    },
    [toolCallId, onRespond],
  )

  const handleFeedback = useCallback(
    (feedback: string) => {
      onRespond?.(toolCallId, {promptId: toolCallId, approved: false, feedback}, COMMAND_TYPES.PLAN_APPROVAL_RESPONSE)
    },
    [toolCallId, onRespond],
  )

  return (
    <PlanApprovalDisplay
      summary={summary}
      actions={actions}
      recommendedAction={recommendedAction}
      onAction={handleAction}
      onFeedback={handleFeedback}
      embedded
      dialogOpen={dialogOpen}
      onDialogClose={onDialogClose}
      disabled={disabled}
    />
  )
}
