import {useState, useCallback, useRef} from 'react'
import {ChatInputDisplay} from './ChatInputDisplay'
import {PromptInput} from './PromptInput'
import {useCreateCommand} from '../../hooks/useCreateCommand'
import {useCLIPromptState} from '../../hooks/use-cli-prompt-state'
import type {CommandType} from '../../types/session'
import {LoadingSkeleton} from '@github-ui/skeleton/LoadingSkeleton'
import {useOptimisticLogs} from '../../contexts/OptimisticLogsContext'
import styles from './ChatInputDisplay.module.css'

interface CLIChatInputProps {
  /** The session ID to send commands to */
  sessionId: string
  /** Callback when a command is successfully sent */
  onCommandSent?: () => void
}

/**
 * Input component for CLI sessions.
 * Shows PromptInput when there's a pending prompt, otherwise shows ChatInputDisplay.
 * Handles both regular message submission and prompt response submission.
 */
export function CLIChatInput({sessionId, onCommandSent}: CLIChatInputProps) {
  const [value, setValue] = useState('')
  const isPromptResponseRef = useRef(false)
  const optimisticIdRef = useRef<string | null>(null)

  const {pendingPrompt, isLoading, markPromptResolved, dismissPrompt} = useCLIPromptState({
    sessionId,
    enabled: true,
  })

  const {addOptimisticResponse, removeOptimisticResponse} = useOptimisticLogs()

  const {createCommand, isPending} = useCreateCommand({
    onSuccess: () => {
      if (isPromptResponseRef.current) {
        markPromptResolved()
        isPromptResponseRef.current = false
      }

      optimisticIdRef.current = null
    },
    onError: () => {
      isPromptResponseRef.current = false
      if (optimisticIdRef.current) {
        removeOptimisticResponse(optimisticIdRef.current)
        optimisticIdRef.current = null
      }
    },
  })

  const handleSubmit = useCallback(() => {
    if (!value.trim() || isPending) return

    createCommand({
      sessionId,
      content: value.trim(),
    })

    setValue('')
    onCommandSent?.()
  }, [value, isPending, sessionId, createCommand, onCommandSent])

  const handlePromptRespond = useCallback(
    (toolCallId: string, response: unknown, commandType: CommandType) => {
      if (!pendingPrompt || isPending) return

      isPromptResponseRef.current = true
      optimisticIdRef.current = addOptimisticResponse({
        toolCallId,
        response,
        commandType,
      })

      createCommand({
        sessionId,
        content: JSON.stringify(response),
        type: commandType,
      })
    },
    [pendingPrompt, isPending, sessionId, createCommand, addOptimisticResponse],
  )

  if (isLoading) {
    return (
      <div className={styles.container}>
        <div className={styles.skeletonWrapper}>
          <LoadingSkeleton variant="rounded" height="100%" width="100%" />
        </div>
      </div>
    )
  }

  if (pendingPrompt) {
    return (
      <PromptInput
        key={pendingPrompt.toolCallId}
        prompt={pendingPrompt}
        onRespond={handlePromptRespond}
        onDismiss={dismissPrompt}
      />
    )
  }

  return (
    <ChatInputDisplay
      value={value}
      onChange={setValue}
      onSubmit={handleSubmit}
      placeholder="Send a message to the CLI session..."
      isSubmitting={isPending}
    />
  )
}
