import {GitHubAvatar} from '@github-ui/github-avatar'
import {sendEvent} from '@github-ui/hydro-analytics'
import {CommentIcon, GearIcon, ListUnorderedIcon, NoteIcon} from '@primer/octicons-react'
import {ActionList, ActionMenu, Link} from '@primer/react'
import {clsx} from 'clsx'
import {useRef, useState} from 'react'

import {CopilotPlan} from '../../utils/copilot-chat-types'
import {useChatStateValues} from '../../utils/CopilotChatContext'
import {useIsCopilotSpacesPage} from '../../utils/custom-copilots-helpers'
import {ManageSharedConversationsDialog} from '../conversation/ManageSharedConversationsDialog'
import {ConversationFeedbackDialog, type FeedbackDialogRef} from '../ConversationFeedbackDialog'
import {PersonalInstructionsDialog} from '../PersonalInstructionsDialog'
import styles from './UserMenu.module.css'

interface UserMenuProps {
  isCondensed?: boolean
}

function getPlanLabel(plan: string | undefined) {
  switch (plan) {
    case CopilotPlan.IndividualFree:
      return 'Free'
    case CopilotPlan.IndividualStudent:
      return 'Student'
    case CopilotPlan.IndividualPro:
      return 'Pro'
    case CopilotPlan.IndividualProPlus:
      return 'Pro+'
    case CopilotPlan.Business:
      return 'Business'
    case CopilotPlan.Enterprise:
      return 'Enterprise'
    default:
      return 'Free'
  }
}

export function UserMenu({isCondensed = false}: UserMenuProps) {
  const anchorRef = useRef<HTMLButtonElement>(null)
  const feedbackRef = useRef<FeedbackDialogRef>(null)
  const [showManageSharedDialog, setShowManageSharedDialog] = useState(false)
  const [showPersonalInstructionsDialog, setShowPersonalInstructionsDialog] = useState(false)
  const {currentUserLogin, plan, optedInToUserFeedback} = useChatStateValues(
    'currentUserLogin',
    'plan',
    'optedInToUserFeedback',
  )
  const isSpacesPage = useIsCopilotSpacesPage()
  const planLabel = `Copilot ${getPlanLabel(plan)}`
  const isFree = !plan || plan === CopilotPlan.IndividualFree

  return (
    <>
      <ActionMenu anchorRef={anchorRef}>
        <ActionMenu.Anchor>
          <button
            className={clsx(styles.userButton, isCondensed && styles.condensed)}
            aria-label={isCondensed ? 'user' : undefined}
          >
            <div className={styles.userAvatar}>
              <GitHubAvatar src={`/${currentUserLogin}.png`} size={24} />
            </div>
            <div className={styles.userContent}>
              {currentUserLogin}
              <div className={styles.planLabel}>{planLabel}</div>
            </div>
          </button>
        </ActionMenu.Anchor>
        <ActionMenu.Overlay width="small" align="end">
          <ActionList>
            <div className={styles.menuItem}>
              <div className={styles.userAvatar}>
                <GitHubAvatar src={`/${currentUserLogin}.png`} size={32} />
              </div>
              <div className={styles.userDetails}>
                <div className={styles.username}>{currentUserLogin}</div>
                <span className={styles.description}>
                  {planLabel}
                  {isFree && (
                    <>
                      {' · '}
                      <Link
                        onClick={() => {
                          sendEvent('dotcom_chat.activate', {
                            target: 'UPGRADE_USER_MENU_LINK',
                            mode: 'immersive',
                          })
                        }}
                        href="https://github.com/github-copilot/pro"
                        className={styles.upgradeLink}
                      >
                        Upgrade
                      </Link>
                    </>
                  )}
                </span>
              </div>
            </div>
            <ActionList.Divider />
            <ActionList.Item
              onSelect={() => {
                setShowPersonalInstructionsDialog(true)
                sendEvent('dotcom_chat.activate', {
                  target: 'USER_MENU_PERSONAL_INSTRUCTIONS',
                  mode: 'immersive',
                })
              }}
            >
              <ActionList.LeadingVisual>
                <NoteIcon />
              </ActionList.LeadingVisual>
              Personal instructions
            </ActionList.Item>
            {!isSpacesPage && (
              <ActionList.Item
                onSelect={() => {
                  setShowManageSharedDialog(true)
                  sendEvent('dotcom_chat.activate', {
                    target: 'USER_MENU_MANAGE_SHARED',
                    mode: 'immersive',
                  })
                }}
              >
                <ActionList.LeadingVisual>
                  <ListUnorderedIcon />
                </ActionList.LeadingVisual>
                Manage shared conversations
              </ActionList.Item>
            )}
            {optedInToUserFeedback && (
              <ActionList.Item
                onSelect={() => {
                  feedbackRef.current?.openDialog()
                  sendEvent('dotcom_chat.activate', {
                    target: 'USER_MENU_GIVE_FEEDBACK',
                    mode: 'immersive',
                  })
                }}
              >
                <ActionList.LeadingVisual>
                  <CommentIcon />
                </ActionList.LeadingVisual>
                Give feedback
              </ActionList.Item>
            )}
            <ActionList.LinkItem
              href="/settings/copilot"
              onClick={() =>
                sendEvent('dotcom_chat.activate', {
                  target: 'USER_MENU_SETTINGS',
                  mode: 'immersive',
                })
              }
            >
              <ActionList.LeadingVisual>
                <GearIcon />
              </ActionList.LeadingVisual>
              Settings
            </ActionList.LinkItem>
          </ActionList>
        </ActionMenu.Overlay>
      </ActionMenu>

      <ConversationFeedbackDialog ref={feedbackRef} mode="immersive" returnFocusRef={anchorRef} />

      {showManageSharedDialog && (
        <ManageSharedConversationsDialog
          closeDialog={() => {
            setShowManageSharedDialog(false)
          }}
          returnFocusRef={anchorRef}
        />
      )}

      {showPersonalInstructionsDialog && (
        <PersonalInstructionsDialog
          onDismiss={() => setShowPersonalInstructionsDialog(false)}
          returnFocusRef={anchorRef}
        />
      )}
    </>
  )
}
