const PAGE_SIZE = 5
const TASK_BUCKET_LABELS = ['Today', 'This week', 'Older'] as const

export type TaskBucketLabel = (typeof TASK_BUCKET_LABELS)[number]

export interface TaskBucket<T> {
  label: TaskBucketLabel
  tasks: T[]
}

export function getTaskBucketTestId(label: TaskBucketLabel): string {
  return `task-bucket-${label.toLowerCase().replace(/\s+/g, '-')}`
}

function getStartOfDay(date: Date): Date {
  const startOfDay = new Date(date)
  startOfDay.setHours(0, 0, 0, 0)
  return startOfDay
}

function getStartOfWeek(date: Date): Date {
  const startOfWeek = getStartOfDay(date)
  startOfWeek.setDate(startOfWeek.getDate() - startOfWeek.getDay())
  return startOfWeek
}

function getTaskBucketLabel(updatedAt: string, now: Date): TaskBucketLabel {
  const updatedAtDate = new Date(updatedAt)

  if (Number.isNaN(updatedAtDate.getTime())) {
    return 'Older'
  }

  const startOfToday = getStartOfDay(now)
  if (updatedAtDate >= startOfToday) {
    return 'Today'
  }

  const startOfCurrentWeek = getStartOfWeek(now)
  if (updatedAtDate >= startOfCurrentWeek) {
    return 'This week'
  }

  return 'Older'
}

export function sortTasksByUpdatedAtDesc<T extends Pick<UITask, 'latest_session_updated_at'>>(tasks: T[]): T[] {
  return [...tasks].sort((leftTask, rightTask) => {
    return (
      new Date(rightTask.latest_session_updated_at).getTime() - new Date(leftTask.latest_session_updated_at).getTime()
    )
  })
}

export function groupTasksByUpdatedAt<T extends Pick<UITask, 'latest_session_updated_at'>>(
  tasks: T[],
  now: Date = new Date(),
): Array<TaskBucket<T>> {
  const buckets = new Map<TaskBucketLabel, T[]>(TASK_BUCKET_LABELS.map(label => [label, []]))

  for (const task of sortTasksByUpdatedAtDesc(tasks)) {
    buckets.get(getTaskBucketLabel(task.latest_session_updated_at, now))?.push(task)
  }

  return TASK_BUCKET_LABELS.map(label => ({label, tasks: buckets.get(label) ?? []})).filter(
    bucket => bucket.tasks.length > 0,
  )
}

export function TaskBucketHeader({label}: {label: TaskBucketLabel}) {
  return (
    <li data-testid={getTaskBucketTestId(label)}>
      <div className="m-0 px-2 py-2 color-fg-muted text-small text-semibold">{label}</div>
    </li>
  )
}

function getPRStatusLabel(task: UITask): string | undefined {
  const {pull} = task
  if (!pull) return undefined
  if (pull.state === 'merged') return 'Merged'
  if (pull.state === 'closed') return 'Closed'
  if (pull.state === 'open' && pull.reviewable_state === 'draft') return 'Draft'
  if (pull.inMergeQueue) return 'Queued to merge'
  return undefined
}

export function getTaskSecondaryText(task: UITask): React.ReactNode {
  if (task.isOptimistic) {
    return 'Initializing...'
  }

  const isActiveSession = task.latest_session_state === 'in_progress' || task.latest_session_state === 'queued'
  const statusText = isActiveSession
    ? getReadableSessionState(task.latest_session_state, {hasPull: !!task.pull})
    : getPRStatusLabel(task) || getReadableSessionState(task.latest_session_state, {hasPull: !!task.pull})

  return (
    <>
      {statusText}
      {task.pull?.number ? ` · #${task.pull.number}` : ''}
      {' · '}
      <RelativeTime format="micro" datetime={task.latest_session_updated_at} />
    </>
  )
}

export function TasksListWrapper({
  viewAllLink,
  showTitle,
  trailingAction,
  onTaskClick,
}: {
  viewAllLink?: React.ReactNode
  showTitle?: boolean
  trailingAction?: React.ReactNode
  onTaskClick?: () => void
}) {
  return (
    <ConsecutiveCAPI401sProvider>
      <ArchiveDialogProvider>
        <TasksList
          viewAllLink={viewAllLink}
          showTitle={showTitle}
          trailingAction={trailingAction}
          onTaskClick={onTaskClick}
        />
      </ArchiveDialogProvider>
    </ConsecutiveCAPI401sProvider>
  )
}

function TasksList({
  viewAllLink,
  showTitle,
  trailingAction,
  onTaskClick,
}: {
  viewAllLink?: React.ReactNode
  showTitle?: boolean
  trailingAction?: React.ReactNode
  onTaskClick?: () => void
}) {
  const location = useLocation()
  const {tasks, isLoading} = useTasks({
    taskFilter: 'active',
    pageSize: PAGE_SIZE,
    includeCounts: true,
  })
  useSSOChangeDetection()

  const visibleTasks = sortTasksByUpdatedAtDesc(tasks).slice(0, PAGE_SIZE)
  const groupedVisibleTasks = groupTasksByUpdatedAt(visibleTasks)
  const isEmpty = visibleTasks.length === 0
  const {isUsingIntentDetection} = useIntentDetection()

  return (
    <>
      <SidebarSection
        title={showTitle ? 'Agent sessions' : undefined}
        isEmpty={isEmpty}
        isLoading={isLoading}
        trailingAction={trailingAction}
      >
        {groupedVisibleTasks.map(bucket => (
          <Fragment key={bucket.label}>
            {groupedVisibleTasks.length > 1 && <TaskBucketHeader label={bucket.label} />}
            {bucket.tasks.map(task => {
              const href = generateTaskPathForRepo({
                repositoryNwo: task.nwo,
                pullRequestNumber: task.pull?.number ?? 0,
                sessionId: task.latest_session_id,
                taskId: task.id,
                isUsingIntentDetection,
              })
              const isSelected = location.pathname === href

              const nwo = task.nwo
              const [owner, repo] = nwo ? nwo.split('/') : [undefined, undefined]

              return (
                <TaskListEntry
                  key={task.clientGeneratedId ?? task.id ?? task.resource_id}
                  task={task}
                  href={href}
                  isSelected={isSelected}
                  reloadDocument
                  secondaryText={getTaskSecondaryText(task)}
                  onTaskClick={onTaskClick}
                  repoOwner={owner}
                  repoName={repo}
                />
              )
            })}
          </Fragment>
        ))}
      </SidebarSection>
      {!isEmpty && viewAllLink}
    </>
  )
}

export interface TaskListEntryProps {
  task: UITask
  href: string
  isSelected: boolean
  secondaryText: string | React.ReactNode
  reloadDocument: boolean
  onTaskClick?: () => void
  repoOwner?: string
  repoName?: string
  currentUserIsOwner?: boolean
}

export function TaskListEntry({
  task,
  href,
  isSelected,
  secondaryText,
  reloadDocument,
  onTaskClick,
  repoOwner,
  repoName,
  currentUserIsOwner,
}: TaskListEntryProps) {
  const anchorRef = useRef<HTMLButtonElement>(null)

  const sessionState = task.latest_session_state
  const prState = task.pull?.state
  const hasPullRequest = !!task.pull
  const isOptimistic = !!task.isOptimistic
  const prInMergeQueue = task.pull?.inMergeQueue
  const isArchived = !!task.archived_at
  const isCLI = isTaskFromCLI(task)
  const isDraftPullRequest = prState === 'open' && task.pull?.reviewable_state === 'draft'
  const isActiveTask = sessionState === 'queued' || sessionState === 'in_progress'

  const trailingAction = (
    <ActionMenu anchorRef={anchorRef}>
      <ActionMenu.Anchor>
        <IconButton
          icon={KebabHorizontalIcon}
          aria-label="Manage session"
          variant="invisible"
          onClick={() =>
            sendEvent('dotcom_chat.activate', {
              target: 'TASK_CONTEXT_MENU',
              mode: 'immersive',
            })
          }
        />
      </ActionMenu.Anchor>
      <ActionMenu.Overlay>
        <TaskActions
          state={task.latest_session_state}
          pull={task.pull}
          taskId={task.id}
          repoOwner={repoOwner}
          repoName={repoName}
          currentUserIsOwner={currentUserIsOwner}
          archivedAt={task.archived_at}
          eventType={task.event_type}
          eventIdentifiers={task.event_identifiers}
        />
      </ActionMenu.Overlay>
    </ActionMenu>
  )

  const effectivePrStatus = isDraftPullRequest ? 'draft' : prState

  const leadingVisual = useCallback(() => {
    if (isCLI || prInMergeQueue || isArchived) {
      return (
        <TaskLeadingVisual
          isOptimistic={isOptimistic}
          prState={prState}
          prInMergeQueue={prInMergeQueue}
          sessionState={sessionState}
          isArchived={isArchived}
          isCLI={isCLI}
        />
      )
    }

    if (isOptimistic || isActiveTask) {
      return (
        <span data-testid="task-list-entry-active-icon" style={{display: 'inline-flex', marginTop: '3px'}}>
          <InProgressSpinner />
        </span>
      )
    }

    if (hasPullRequest) {
      return getPRStatusIcon(effectivePrStatus || 'open')
    }

    if (sessionState === 'completed') {
      return <CheckIcon className="fgColor-success" data-testid="task-list-entry-completed-icon" />
    }

    if (sessionState === 'failed' || sessionState === 'timed_out' || sessionState === 'cancelled') {
      return <StopIcon className="fgColor-danger" data-testid="task-list-entry-error-icon" />
    }

    return <DotFillIcon className="fgColor-muted" data-testid="task-list-entry-inactive-icon" />
  }, [
    isCLI,
    prInMergeQueue,
    isArchived,
    isOptimistic,
    prState,
    sessionState,
    isActiveTask,
    hasPullRequest,
    effectivePrStatus,
  ])

  return (
    <SidebarListItem
      href={href}
      text={getTaskTitle(task, task.pull?.title)}
      leadingVisual={leadingVisual}
      isSelected={isSelected}
      trailingAction={trailingAction}
      secondaryText={secondaryText}
      reloadDocument={reloadDocument}
      onClick={() => {
        onTaskClick?.()
        sendEvent('agent_sessions.task_view', {
          target: 'VIEW_TASK_FROM_MISSION_CONTROL',
          task_id: task.resource_global_id,
        })
      }}
    />
  )
}

export function isOpenTask(task: UITask): boolean {
  return !task.pull || (task.pull.state !== 'merged' && task.pull.state !== 'closed')
}

export function isOptimisticTask(task: UITask): task is OptimisticTask {
  return !!task.isOptimistic
}
