import {Link} from '@primer/react'
import type {PublicUser} from '../../../types/public-user'
import styles from './UserInitialMessage.module.css'
import {clsx} from 'clsx'
import type {Session} from '../../../types/session'
import {sendEvent} from '@github-ui/hydro-analytics'
import {ExpandableMarkdown} from '../../expandable-markdown/ExpandableMarkdown'
import {GitHubAvatar} from '@github-ui/github-avatar'
import {useAgentInfo} from '../../../hooks/use-agent-info'
import {createMarkdownWithAgentLinks} from '../../../utils/markdown-link-utils'
import {useIntentDetection} from '../../../hooks/useIntentDetection'

const mobileEventTypes = [
  'ios_mobile_mission_control',
  'android_mobile_mission_control',
  'ios_mobile_repo_profile',
  'android_mobile_repo_profile',
]

function getDisplayName(isCurrentUserTheCreator: boolean, sessionOwner?: PublicUser) {
  if (isCurrentUserTheCreator) return 'You'
  if (sessionOwner?.login) return sessionOwner.login
  return 'User'
}

function getAvatarUrl(sessionOwner?: PublicUser) {
  if (sessionOwner?.primaryAvatarUrl) return sessionOwner.primaryAvatarUrl
  if (sessionOwner?.login) return `https://avatars.githubusercontent.com/${sessionOwner.login}`
  return 'https://avatars.githubusercontent.com/ghost'
}

interface UserInitialMessageProps {
  threadId?: string
  currentUser?: PublicUser
  sessionOwner?: PublicUser
  session: Session
  message: string
  agentId?: number | null
}

export const UserInitialMessage = ({
  currentUser,
  sessionOwner,
  threadId,
  session,
  message,
  agentId,
}: UserInitialMessageProps) => {
  const {data: agentInfo} = useAgentInfo(agentId)
  const generateOrigin = (linkText: string, url?: string | null, article?: string) => {
    const prefix = article ? ` from ${article} ` : ' from '

    return (
      <>
        {prefix}
        {url ? (
          <Link
            href={url}
            inline
            onClick={() => {
              sendEvent('agent_sessions.task_view', {
                target: 'VIEW_SESSION_LINK',
                session_id: session.id,
                task_id: session.resource_global_id,
                thread_id: threadId,
              })
            }}
          >
            {linkText}
          </Link>
        ) : (
          <span>{linkText}</span>
        )}
      </>
    )
  }

  const eventInformation = () => {
    const type = session.event_type
    const identifiers = session.event_identifiers
    const url = session.event_url

    // Handle conversation threads that don't have an event_url yet
    if (threadId) {
      return generateOrigin('conversation', `${window.location.origin}/copilot/c/${threadId}`, 'a')
    }

    if (!type) {
      return null
    }

    // Event identifiers that we want to show are in the format of `signal::additional::information`
    // and will be handled on a case by case basis dependent on the type
    if (type === 'fix_failed_workflow') {
      return generateOrigin('GitHub Actions', url)
    } else if (type === 'issues_agent_assignment') {
      const issueNumber = identifiers?.find(id => id.startsWith('issue::'))?.split('::')[1]

      // In case the issue number can't be found
      if (!issueNumber) {
        return generateOrigin('issue', url, 'an')
      }

      return generateOrigin(`issue #${issueNumber}`, url)
    } else if (type === 'linear_webhook') {
      return generateOrigin('Linear', url)
    } else if (type === 'jira_issue') {
      return generateOrigin('Jira', url)
    } else if (mobileEventTypes.includes(type)) {
      return generateOrigin('GitHub Mobile')
    }

    return null
  }

  const content = session.event_content
  const isCurrentUserTheCreator = currentUser?.id === session.user_id
  const displayName = getDisplayName(isCurrentUserTheCreator, sessionOwner)
  const avatarUrl = getAvatarUrl(sessionOwner)

  const {isChatSession} = useIntentDetection(session)

  return (
    <div className={styles.container}>
      <div className={styles.messageBubble}>
        {!isChatSession && (
          <p
            className={clsx(styles.meta, {
              [styles.metaSmall]: !!content,
            })}
          >
            <span>{displayName}</span> {message}
            {eventInformation()}
          </p>
        )}

        {content && (
          <ExpandableMarkdown
            className={styles.agentMentionText}
            markdown={agentInfo ? createMarkdownWithAgentLinks(content, agentInfo) : content}
          />
        )}
      </div>
      <div className={styles.avatarContainer}>
        <GitHubAvatar src={avatarUrl} size={24} />
      </div>
    </div>
  )
}
