import {isCompletionChunk, type LogEntry} from '../../../types/session'
import {useLogs} from '../../../hooks/useLogs'
import {useCurrentUser} from '../../../contexts/CurrentUserContext'
import {CopilotMessageBubble, CopilotMessageContainer, CopilotMessageLoading} from './CopilotMessageBubble'
import {PlanApprovalDisplay} from '../../session-logs/PlanApprovalDisplay'
import {ResolvedPlanStatus} from '../../session-logs/ResolvedPlanStatus'
import {hasPrMetadataTags} from '../../../utils/pr-metadata-tags'
import {getCustomAgentId} from '../../../utils/group-agent-logs'
import {isFeatureEnabled} from '@github-ui/feature-flags'

/** CCA-specific actions for end-of-session plan approval */
export const CCA_PLAN_ACTION_IMPLEMENT = 'implement'
export const CCA_PLAN_ACTION_EXIT = 'exit_only'
export const CCA_PLAN_ACTIONS = [CCA_PLAN_ACTION_IMPLEMENT, CCA_PLAN_ACTION_EXIT]

interface CopilotFinalPlanMessageProps {
  logsPollingInterval: number
  /** Called when the user approves the plan — parent should kick off a new session */
  onApprove?: (action: string, planSummary: string) => void
  /** Called when the user submits feedback on the plan */
  onFeedback?: (feedback: string) => void
  /** Whether the plan has already been approved — shows the resolved chip */
  isResolved?: boolean
}

export function CopilotFinalPlanMessage({
  logsPollingInterval,
  onApprove,
  onFeedback,
  isResolved = false,
}: CopilotFinalPlanMessageProps) {
  const {currentUserIsSessionOwner} = useCurrentUser()
  const richPlanUIEnabled = isFeatureEnabled('copilot_mission_control_rich_plan_ui')
  const {
    data: logsData,
    isLoading: logsIsLoading,
    error: logsError,
  } = useLogs({logsPollingInterval, batchCompletedSessions: true, currentUserIsSessionOwner})

  const stopMessages = extractStopMessages(logsData)

  if (logsIsLoading) {
    return <CopilotMessageLoading />
  }

  if (logsError || stopMessages.length === 0) {
    return null
  }

  const combinedSummary = stopMessages.map(m => m.content).join('\n\n')

  if (!richPlanUIEnabled) {
    return (
      <CopilotMessageContainer>
        {stopMessages.map((message, index) => (
          <CopilotMessageBubble key={message.id} markdown={message.content} showAvatar={index === 0} />
        ))}
      </CopilotMessageContainer>
    )
  }

  if (isResolved) {
    return <ResolvedPlanStatus />
  }

  return (
    <PlanApprovalDisplay
      summary={combinedSummary}
      planContent={combinedSummary}
      actions={CCA_PLAN_ACTIONS}
      recommendedAction="implement"
      onAction={action => onApprove?.(action, combinedSummary)}
      onFeedback={onFeedback}
    />
  )
}

/**
 * Extracts assistant stop messages from log entries, excluding PR metadata.
 * Usually there is only one that isn't a PR description. This ensures we don't lose any messages if there are multiple stop entries.
 */
function extractStopMessages(logsData: LogEntry[] = []): Array<{id: string; content: string}> {
  const messages: Array<{id: string; content: string}> = []

  for (const logEntry of logsData) {
    if (!isCompletionChunk(logEntry)) continue

    // Skip subagent entries - their stop messages stay in the grouped logs
    if (getCustomAgentId(logEntry)) continue

    const choice = logEntry.choices[0]
    if (
      choice?.finish_reason === 'stop' &&
      choice.delta.role === 'assistant' &&
      choice.delta.content &&
      !choice.delta.tool_calls &&
      // Exclude PR description entries - we want the summary, not the PR metadata
      !hasPrMetadataTags(choice.delta.content)
    ) {
      const content = choice.delta.content.trim()
      if (content) {
        messages.push({id: logEntry.id, content})
      }
    }
  }

  return messages
}
