export function TaskChat({
  showHeader = false,
  isRepoAgentsView = false,
  forceV2Input = false,
  repoOwner,
  repoName,
  taskId,
  branchAliveChannel,
  task,
  ...payload
}: TaskChatProps) {
  const {
    agentMentions,
    pull,
    sessions,
    logsPollingInterval = 3000,
    sessionsPollingInterval = 3000,
    sessionOwners: initialSessionOwners,
    currentUserCanPush,
  } = payload

  const effectiveTaskId = taskId ?? pull?.global_relay_id
  const repoNwo = repoOwner && repoName ? `${repoOwner}/${repoName}` : undefined
  const viewMode = useViewMode()
  const isSidePanel = viewMode === 'sidePanel'

  // Compute effective nwo: prefer repoNwo (repo-agents view) over pull's nwo
  const effectiveNwo = repoNwo ?? pull?.repository_nwo

  const useScrollToBottomButton =
    isRepoAgentsView && isFeatureEnabled('copilot_mission_control_scroll_to_bottom_button')
  const [searchParams] = useSearchParams()
  const urlSessionId = searchParams.get('session_id')
  const {currentUser, currentUserIsSessionOwner} = useCurrentUser()
  const [highlightedSessionId, setHighlightedSessionId] = useState<string | null>(
    currentUserIsSessionOwner && urlSessionId ? urlSessionId : null,
  )
  // Prevents multiple calls to removeSessionIdFromUrl for the same urlSessionId (e.g., from multiple event handlers firing).
  const sessionIdClearedRef = useRef(false)

  const scrollContainerRef = useRef<HTMLDivElement>(null)
  const sentinelRef = useRef<HTMLDivElement>(null)
  const chatInputRef = useRef<ChatInputRef>(null)
  const textAreaRef = useRef<HTMLTextAreaElement>(null)

  const decoupledModeEnabled = isFeatureEnabled('copilot_mission_control_decoupled_mode')
  const collapsedSessionsEnabled = isFeatureEnabled('copilot_mission_control_collapsed_sessions')
  const initialDataSpinnerEnabled = isFeatureEnabled('copilot_mission_control_initial_data_spinner')

  const {streamingState, pendingChatMessage, clearPendingChat, latestChatSessionId, getChatMessageHistory} =
    useChatStreamContext()
  const {isUsingIntentDetection} = useIntentDetection()

  const {data: taskData} = useTask({
    owner: repoOwner,
    repo: repoName,
    taskId,
    initialTask: task,
  })

  const {createSession: createNewSession} = useCreateAPISession()
  const {mutate: patchSession} = usePatchSession({
    onError: (_error, variables) => {
      setOptimisticPlanStates(prev => {
        const next = {...prev}
        delete next[variables.session_id]
        return next
      })
    },
  })

  const handlePlanApprove = (session: SessionType) => (action: string, planSummary: string) => {
    if (!effectiveNwo || !effectiveTaskId) return
    if (action === CCA_PLAN_ACTION_EXIT) {
      updatePlanState(session.id, PLAN_STATE_DISMISSED)
      textAreaRef.current?.focus()
      return
    }
    updatePlanState(session.id, PLAN_STATE_APPROVED)
    const prompt = action === CCA_PLAN_ACTION_IMPLEMENT ? `Implement the plan:\n\n${planSummary}` : action
    createNewSession({
      nwo: effectiveNwo,
      taskId: effectiveTaskId,
      problemStatement: prompt,
      eventType: 'agent_task_post_session_steering',
    })
  }

  const isCLI = isAPITaskFromCLI(taskData)

  // When the agent creates a PR, the task artifacts will contain a github_resource artifact.
  // Use usePullRequest to reactively fetch the PR data without a full page reload.
  const taskPullRequestId = taskData ? getGitHubArtifactData(taskData.artifacts)?.id : undefined
  const {data: detectedPull} = usePullRequest({
    pullRequestId: !pull ? taskPullRequestId : undefined,
    includeBody: false,
    refetchOnMount: true,
  })

  // Use the detected PR if the original payload didn't include one
  const effectivePull = pull ?? detectedPull
  const effectivePayload = {...payload, pull: effectivePull}

  const {
    data: sessionsData,
    isError: sessionsIsError,
    timedOut: sessionsTimedOut,
    isFetchedAfterMount: notUsingSessionInitialData,
  } = useSessions({
    pullId: effectivePull?.id,
    taskId,
    initialData: sessions,
    sessionsPollingInterval,
    clearPendingChat,
  })

  const hasActiveSession = sessionsData?.some(isActiveSession) ?? false

  // Derive plan states from session event_identifiers
  // plus local optimistic state for immediate UI feedback before polling catches up
  const [optimisticPlanStates, setOptimisticPlanStates] = useState<Record<string, PlanState>>({})

  const planStates = useMemo(() => {
    const states: Record<string, PlanState> = {}
    const confirmedIds = new Set<string>()
    if (sessionsData) {
      for (const session of sessionsData) {
        if (session.event_identifiers?.includes(PLAN_EVENT_APPROVED)) {
          states[session.id] = PLAN_STATE_APPROVED
          confirmedIds.add(session.id)
        } else if (session.event_identifiers?.includes(PLAN_EVENT_DISMISSED)) {
          states[session.id] = PLAN_STATE_DISMISSED
          confirmedIds.add(session.id)
        }
      }
    }
    // Layer in optimistic entries that the server hasn't confirmed yet
    for (const [sessionId, state] of Object.entries(optimisticPlanStates)) {
      if (!confirmedIds.has(sessionId)) {
        states[sessionId] = state
      }
    }
    return states
  }, [sessionsData, optimisticPlanStates])

  const updatePlanState = (sessionId: string, state: PlanState) => {
    const freshSession = sessionsData?.find(s => s.id === sessionId)
    if (!freshSession) return
    const newEventIdentifiers = [...(freshSession.event_identifiers ?? []), PLAN_STATE_TO_EVENT[state]]
    setOptimisticPlanStates(prev => ({...prev, [sessionId]: state}))
    patchSession({
      user_id: freshSession.user_id,
      session_id: freshSession.id,
      task_id: freshSession.task_id,
      event_identifiers: newEventIdentifiers,
    })
  }

  const diffOverlay = useDiffOverlay({
    artifacts: taskData?.artifacts,
    pullBaseRef: effectivePull?.base_ref_name,
    pullHeadRef: effectivePull?.head_ref_name,
    hasActiveSession,
  })

  const {data: sessionOwners} = useSessionOwners({
    sessions: sessionsData,
    initialData: initialSessionOwners,
  })

  const mostRecentSession = sessionsData?.[sessionsData.length - 1]

  // Fetch mentions for the current sessions
  const {data: mentions, isFetching: isFetchingMentions} = useAgentMentions({
    pull: effectivePull,
    sessions: sessionsData,
    initialData: agentMentions ?? [],
    agentId: mostRecentSession?.agent_id,
  })

  // Manage pending sessions and mentions
  const {allSessions, allMentions, addPendingSession, clearPendingSession} = usePendingSession({
    pullId: effectivePull?.id,
    taskId: effectiveTaskId,
    sessions: sessionsData,
    mentions,
    currentUser,
  })

  const clearPending = () => {
    clearPendingSession()
  }

  // For 'readonly' sessions like Copilot code review
  const everySessionReadonly = sessionsData?.every(s => isReadonlyAgent(s)) ?? false

  // Sort sessions by creation time
  const sortedSessions = allSessions.sort((a, b) => new Date(a.created_at).getTime() - new Date(b.created_at).getTime())
  const lastSession = allSessions.at(-1)

  const {
    data: inactiveLogs,
    isLoading: inactiveLogsIsLoading,
    isFetching: inactiveLogsIsFetching,
  } = useInactiveLogs({
    sessions: sortedSessions,
    pullId: effectivePull?.id,
    repoOwner,
    repoName,
    taskId,
  })

  // Extract thread ID from the copilot-chat-spec-task session's event identifiers (feature flagged)
  const isTaskHyperlinkingEnabled = isFeatureEnabled('copilot_immersive_task_hyperlinking')
  const threadId = isTaskHyperlinkingEnabled
    ? (() => {
        const specTaskSession = allSessions.find(session => session.event_type === COPILOT_CHAT_SPEC_TASK_EVENT_TYPE)
        return extractSpecTaskThreadIdFromEventIdentifiers(specTaskSession?.event_identifiers)
      })()
    : undefined

  // Function to get the mention for a specific session
  const getMentionForSession = (session: SessionType): AgentMention | undefined => {
    if (!allMentions || !session.event_identifiers) {
      return undefined
    }

    // There should only be one mention
    return allMentions.find(mention => session.event_identifiers?.includes(mention.id.toString()))
  }

  // Determine which session should be expanded by default
  const getDefaultOpenState = (sessionId: string, index: number, isPending: boolean) => {
    if (urlSessionId) {
      // If a specific session ID is provided in URL, expand that session
      return sessionId === urlSessionId
    }

    // We're expanding pending sessions by default
    if (isPending) {
      return true
    }

    // If there's an active session, that one takes precedence unless explicitly provided above
    if (sessionsData && sessionsData.some(session => isActiveSession(session))) {
      return sessionId === sessionsData.find(session => isActiveSession(session))?.id
    }

    // Otherwise, expand the most recent session (last in the sorted array)
    if (collapsedSessionsEnabled) {
      return false
    }
    return index === sortedSessions.length - 1
  }

  const {scrollToBottom} = useScrollToBottom({
    containerRef: scrollContainerRef,
    behavior: 'smooth',
  })
  const {setIsAtBottom} = useStickToBottom({
    containerRef: scrollContainerRef,
    sentinelRef,
    offset: 4,
    initialStickToBottom: !useScrollToBottomButton,
    resetKey: effectiveTaskId,
  })

  const removeSessionIdFromUrl = useCallback(() => {
    if (!urlSessionId) return
    if (typeof window === 'undefined') return
    if (sessionIdClearedRef.current) return

    sessionIdClearedRef.current = true
    const newParams = new URLSearchParams(searchParams)
    newParams.delete('session_id')
    const searchString = newParams.toString()
    const newUrl = `${window.location.pathname}${searchString ? `?${searchString}` : ''}${window.location.hash}`
    addUrlToHistoryStack(newUrl)
    queueMicrotask(() => setHighlightedSessionId(null))
  }, [searchParams, urlSessionId])

  // If the user clicks outside the highlighted session, remove the session_id from the URL (and un-highlight the session).
  const handleContainerClick = (event: React.MouseEvent) => {
    if (!highlightedSessionId) return

    const target = event.target as HTMLElement
    const highlightedSession = scrollContainerRef.current?.querySelector(`[data-session-id="${highlightedSessionId}"]`)

    if (highlightedSession && !highlightedSession.contains(target)) {
      removeSessionIdFromUrl()
    }
  }

  // If session_id changes in the URL, reset sessionIdClearedRef to allow possible removal of it from the URL.
  useEffect(() => {
    sessionIdClearedRef.current = false
  }, [urlSessionId])

  useEffect(() => {
    if (urlSessionId) {
      setIsAtBottom(false)
    }
  }, [urlSessionId, setIsAtBottom])

  // Handle diff events to populate chat input with file references
  useDiffEventHandler({
    chatInputRef,
    textAreaRef,
    isReadonly: everySessionReadonly,
    taskId: effectiveTaskId ?? '',
  })

  // Remove session_id from URL when a new session becomes active.
  useEffect(() => {
    if (!urlSessionId) return
    if (!sessionsData) return

    const activeSession = sessionsData.find(isActiveSession)
    const activeSessionId = activeSession?.id ?? null

    if (!activeSessionId) return
    if (activeSessionId === urlSessionId) return

    removeSessionIdFromUrl()
  }, [urlSessionId, sessionsData, removeSessionIdFromUrl])

  // Clear chat input when switching tasks/pulls
  useEffect(() => {
    if (chatInputRef.current) {
      chatInputRef.current.setText('')
    }

    if (urlSessionId) {
      setIsAtBottom(false)
      return
    }

    if (!useScrollToBottomButton) {
      setIsAtBottom(true)
      // Only scroll the container, not the window. Guard against null container ref
      // which can happen during initial render before sessions data loads.
      if (scrollContainerRef.current) {
        scrollToBottom({behavior: 'instant'})
      }
    }
  }, [effectiveTaskId, setIsAtBottom, scrollToBottom, urlSessionId, useScrollToBottomButton])

  // Determine whether the pending chat section should be shown, and in what mode.
  //
  // showPendingUserMessage: We have a pending message and are still waiting for the server
  // to respond (streamingState === 'requested'). This naturally hides the pending message
  // after a 201 mid-session steering response (which goes straight to 'closed' without
  // streaming), since the message is already delivered as a command to the active session.
  //
  // showStreamingChatBridge: The streaming response has started (or finished) for a new
  // chat session but that session hasn't appeared in the sessions list yet (useSessions
  // hasn't polled it). We bridge the gap by rendering part of getChatMessageHistory() and
  // the planning spinner so we don't get a blank area waiting on the session to load.
  const latestChatSessionLoaded = latestChatSessionId ? sortedSessions.some(s => s.id === latestChatSessionId) : true
  const showPendingUserMessage = isUsingIntentDetection && !!pendingChatMessage && streamingState === 'requested'
  const showStreamingChatBridge = isUsingIntentDetection && !!latestChatSessionId && !latestChatSessionLoaded

  // When bridging the gap before a new chat session loads, recover the flushed user
  // message from getChatMessageHistory (pendingChatMessage was already cleared by
  // setStreamingChatResponse). We only grab the first entry and skip the streaming
  // assistant response to avoid a glitchy content swap when the full session loads.
  const bridgeUserMessage =
    showStreamingChatBridge && latestChatSessionId
      ? getChatMessageHistory(latestChatSessionId).find(msg => msg.role === 'user')
      : null

  return !sessionsData || !sessionOwners ? (
    <CenteredSpinner />
  ) : sessionsIsError && sessionsTimedOut ? (
    <CenteredBlankSlate
      title="Activity cannot be loaded"
      description="The activity on this task is temporarily unavailable due to a system error. Try reloading the page, or if the problem persists, contact support."
      statusLink="https://www.githubstatus.com/"
    />
  ) : !sessionsData.length && initialDataSpinnerEnabled && !notUsingSessionInitialData ? (
    <CenteredSpinner />
  ) : !sessionsData.length ? (
    <CenteredBlankSlate
      title="This task is not viewable"
      description={`You can't view this task because you do not have any active sessions${
        effectivePull ? ' for this pull request' : ''
      }.`}
      pullLink={effectivePull?.url}
    />
  ) : (
    <OptimisticLogsProvider sessionId={isCLI ? lastSession?.id : undefined}>
      <div className={styles.root}>
        <div className={styles.container}>
          <div className={styles.diffOverlayWrapper}>
            <div className={clsx(styles.stickableContainer, diffOverlay.isOpen && styles.stickableContainerFrozen)}>
              <ChatScrollContainer
                containerRef={scrollContainerRef}
                disabled={false}
                className={styles.scrollContainer}
                onClick={handleContainerClick}
              >
                {useScrollToBottomButton && <ScrollToBottomButton />}
                <div
                  className={clsx(
                    styles.content,
                    isRepoAgentsView && styles.repoAgentsViewContent,
                    isSidePanel && styles.sidePanelContent,
                  )}
                >
                  {showHeader && (
                    <TaskChatHeader
                      sessions={sortedSessions}
                      sessionOwners={sessionOwners}
                      pull={effectivePull}
                      task={taskData}
                      repoOwner={repoOwner}
                      repoName={repoName}
                    />
                  )}
                  {sortedSessions.map((session, index) => {
                    const isFirstSession = index === 0
                    const mention = getMentionForSession(session)
                    const isPending = isPendingSession(session)
                    const isReadonly = isReadonlyAgent(session)
                    const sessionOwner = sessionOwners.find(owner => owner.id === session.user_id)

                    return (
                      <div className="d-flex flex-column" key={session.id}>
                        {/* Skip initial messages for CLI sessions - they don't have meaningful "started a task" context */}
                        {isFirstSession &&
                          !isCLI && ( // Render the initial timeline messages only for the first session
                            <div className={styles.initialMessages}>
                              <UserInitialMessage
                                currentUser={currentUser}
                                sessionOwner={sessionOwner}
                                threadId={threadId}
                                session={session}
                                message={isReadonly ? 'requested a review' : 'started a task'}
                                agentId={session.agent_id}
                              />
                              <CopilotInitialMessage
                                session={session}
                                message={isReadonly ? 'started a review' : 'started work'}
                              />
                            </div>
                          )}
                        {/* Subsequent sessions: show PR comment mention or problem statement */}
                        {!isFirstSession && !isReadonly && (mention || isFetchingMentions) && (
                          <UserMessage
                            key={mention?.id}
                            mention={mention}
                            isLoading={!mention && isFetchingMentions}
                            agentId={session.agent_id}
                          />
                        )}
                        {!isFirstSession && !isReadonly && !mention && !isFetchingMentions && (
                          <UserProblemStatementMessage session={session} sessionOwner={sessionOwner} />
                        )}
                        {/* Readonly sessions need different messaging */}
                        {!isFirstSession && isReadonly && (
                          <div className={styles.readonlyMessageContainer}>
                            <CopilotInitialMessage session={session} message="started a review" />
                          </div>
                        )}
                        <SessionContextProvider
                          session={session}
                          sessionOwner={sessionOwner}
                          logs={inactiveLogs?.[session.id]}
                          logsAreLoading={
                            inactiveLogsIsLoading ||
                            (inactiveLogsIsFetching && inactiveLogs?.[session.id] === undefined)
                          }
                        >
                          <Session
                            defaultOpen={getDefaultOpenState(session.id, index, isPending)}
                            scrollContainerRef={scrollContainerRef}
                            hideStopButton={isPending}
                            onOpenChange={() => setIsAtBottom(false)}
                            onToolExpand={() => setIsAtBottom(false)}
                            shouldHighlight={session.id === highlightedSessionId}
                            stickyHeaders={!isRepoAgentsView} // We don't want sticky headers in repo agents view
                            currentUserCanPush={currentUserCanPush}
                            pull={effectivePull}
                            logsPollingInterval={logsPollingInterval}
                            currentUser={currentUser}
                            nwo={effectiveNwo}
                          />
                          {session.state === 'completed' && (
                            <>
                              {/* Copilot never has a reply on the first session, but in single session view we can't tell, so show it to be safe */}
                              {((currentUserIsSessionOwner && !isFirstSession) || !currentUserIsSessionOwner) &&
                                (decoupledModeEnabled ? (
                                  <CopilotReplyMessage logsPollingInterval={logsPollingInterval ?? 3000} />
                                ) : (
                                  <LegacyCopilotMessage logsPollingInterval={logsPollingInterval ?? 3000} />
                                ))}
                              {decoupledModeEnabled &&
                                MISSION_CONTROL_EVENT_TYPES.includes(session.event_type ?? '') &&
                                planStates[session.id] !== PLAN_STATE_DISMISSED &&
                                (planStates[session.id] === PLAN_STATE_APPROVED ||
                                  index === sortedSessions.length - 1) && (
                                  <CopilotFinalPlanMessage
                                    logsPollingInterval={logsPollingInterval ?? 3000}
                                    onApprove={
                                      planStates[session.id] === PLAN_STATE_APPROVED
                                        ? undefined
                                        : handlePlanApprove(session)
                                    }
                                    isResolved={planStates[session.id] === PLAN_STATE_APPROVED}
                                  />
                                )}
                            </>
                          )}
                        </SessionContextProvider>
                      </div>
                    )
                  })}
                  {(showPendingUserMessage || showStreamingChatBridge) && (
                    <>
                      {showPendingUserMessage && sortedSessions[sortedSessions.length - 1]?.event_type !== 'chat' && (
                        <LogChatMessage logEntry={pendingChatMessage as ChatMessage} />
                      )}
                      {showStreamingChatBridge && bridgeUserMessage && (
                        <LogChatMessage logEntry={bridgeUserMessage as ChatMessage} />
                      )}
                      <Stack direction="horizontal" padding="normal" align="center" justify="start" gap="condensed">
                        <AgentAvatar animationType={CopilotAnimationType.Thinking} loopAnimation />
                        <WithShimmerEffect className="color-fg-muted">Planning response...</WithShimmerEffect>
                      </Stack>
                    </>
                  )}
                  {/* used for auto-scrolling */}
                  <div ref={sentinelRef} aria-hidden style={{height: 1}} />
                </div>
              </ChatScrollContainer>
            </div>
            {!effectivePull && diffOverlay.baseRef && diffOverlay.headRef && repoNwo && effectiveTaskId && (
              <DiffOverlay
                isOpen={diffOverlay.isOpen}
                onClose={diffOverlay.close}
                repoNwo={repoNwo}
                taskId={effectiveTaskId}
                baseRef={diffOverlay.baseRef}
                headRef={diffOverlay.headRef}
                initialFilePath={diffOverlay.initialFilePath}
              />
            )}
          </div>
          {!everySessionReadonly && (
            <div className={clsx(styles.chatInputContainer, isRepoAgentsView && styles.repoAgentsViewChatInput)}>
              {isCLI && lastSession ? (
                <CLIChatInput sessionId={lastSession.id} onCommandSent={scrollToBottom} />
              ) : (isRepoAgentsView || forceV2Input) && repoNwo ? (
                taskData ? (
                  <TaskChatInputV2
                    taskAgentId={allSessions[0]?.agent_id}
                    activeSession={allSessions?.find(isActiveSession) ?? null}
                    onAddPendingSession={addPendingSession}
                    onClearPendingSession={clearPending}
                    payload={effectivePayload}
                    scrollToBottom={scrollToBottom}
                    repoNwo={repoNwo}
                    task={taskData}
                    branchAliveChannel={branchAliveChannel}
                    onCloseDiff={diffOverlay.onCloseDiff}
                    onViewDiff={diffOverlay.onViewDiff}
                  />
                ) : null
              ) : (
                <TaskChatInput
                  taskAgentId={allSessions[0]?.agent_id}
                  activeSession={allSessions?.find(isActiveSession) ?? null}
                  onAddPendingSession={addPendingSession}
                  onClearPendingSession={clearPendingSession}
                  payload={effectivePayload}
                  scrollToBottom={scrollToBottom}
                  chatInputRef={chatInputRef}
                  inputRef={textAreaRef}
                />
              )}
            </div>
          )}
        </div>
      </div>
    </OptimisticLogsProvider>
  )
}
