import type {ReactNode} from 'react'
import {useState} from 'react'
import {clsx} from 'clsx'
import {DashIcon, ChevronRightIcon} from '@primer/octicons-react'
import styles from './UserChoiceCard.module.css'

export interface UserChoiceCardProps {
  /** Card title (shown in header) — supports ReactNode for markdown */
  title: ReactNode
  /** Optional subtitle (muted, shown after title) */
  subtitle?: ReactNode
  /** Additional buttons rendered in the header row (e.g. fullscreen icon) */
  headerButtons?: ReactNode
  /** Preview content rendered above choices (e.g. plan markdown, command detail) */
  previewContent?: ReactNode
  /** Choice rows — typically ChoiceButtonGroup */
  children?: ReactNode
  /** Footer buttons below choices (e.g. Submit, Skip) */
  footerButtons?: ReactNode
  /** When true, hides container chrome (border, background) for embedding in another container */
  embedded?: boolean
  /** Whether the card content is expanded */
  isExpanded?: boolean
  /** Callback when expand/collapse is toggled */
  onToggle?: () => void
}

/** Shared card wrapper for active interactive user prompts */
export function UserChoiceCard({
  title,
  subtitle,
  headerButtons,
  previewContent,
  children,
  footerButtons,
  embedded = false,
  isExpanded: isExpandedProp,
  onToggle,
}: UserChoiceCardProps) {
  const [isExpandedInternal, setIsExpandedInternal] = useState(true)
  const isControlled = isExpandedProp !== undefined
  const isExpanded = isControlled ? isExpandedProp : isExpandedInternal

  const handleToggle = () => {
    if (!isControlled) {
      setIsExpandedInternal(prev => !prev)
    }
    onToggle?.()
  }

  // Active state: interactive card
  return (
    <div className={clsx(styles.card, embedded && styles.embedded)}>
      {!embedded && (
        <div className={styles.header}>
          <div className={styles.headerText}>
            <div className={styles.title}>{title}</div>
            {subtitle ? <div className={styles.subtitle}>{subtitle}</div> : null}
          </div>
          <div className={styles.headerActions}>
            {headerButtons}
            <button
              type="button"
              className={styles.collapseButton}
              onClick={handleToggle}
              aria-label={isExpanded ? 'Collapse' : 'Expand'}
              aria-expanded={isExpanded}
            >
              {isExpanded ? <DashIcon size={16} /> : <ChevronRightIcon size={16} />}
            </button>
          </div>
        </div>
      )}
      {isExpanded && (
        <div className={styles.content}>
          {previewContent ? <div className={styles.previewContent}>{previewContent}</div> : null}
          {children ? <div className={styles.choices}>{children}</div> : null}
          {footerButtons ? <div className={styles.footerButtons}>{footerButtons}</div> : null}
        </div>
      )}
    </div>
  )
}
