import {useEffect, useCallback, useState, useRef} from 'react'
import {useScrollToBottom} from './use-scroll-to-bottom'

type UseStickToBottomOptions = {
  // container element to observe and scroll or use null/undefined for window/viewport scrolling.
  containerRef?: React.RefObject<HTMLElement | null>
  // The sentinel element placed at the end of the scrollable content
  sentinelRef: React.RefObject<HTMLElement | null>
  // positive px moves the trigger up to fire before the true bottom
  offset?: number
  // scroll behavior for programmatic scrolls
  scrollBehavior?: ScrollBehavior
  // When false, the ResizeObserver won't auto-scroll on initial async content load
  initialStickToBottom?: boolean
  // When this value changes, internal scroll tracking state is reset
  resetKey?: string
}

export function useStickToBottom({
  containerRef,
  sentinelRef,
  offset,
  scrollBehavior = 'instant',
  initialStickToBottom = true,
  resetKey,
}: UseStickToBottomOptions) {
  const [isAtBottom, setIsAtBottom] = useState(initialStickToBottom)

  // track if user has ever manually scrolled
  const hasScrolledRef = useRef(false)

  // use a ref to always have the latest isAtBottom value
  // this avoids effect re-runs and observer re-creation on every isAtBottom change
  const isAtBottomRef = useRef(isAtBottom)
  useEffect(() => {
    isAtBottomRef.current = isAtBottom
  }, [isAtBottom])

  // Reset isAtBottom state during render when resetKey changes (e.g. navigating between tasks).
  // Uses state comparison (not refs) to comply with React Compiler rules.
  // Ref resets happen in the scroll listener effect below.
  const [prevResetKey, setPrevResetKey] = useState(resetKey)
  if (resetKey !== undefined && prevResetKey !== resetKey) {
    setPrevResetKey(resetKey)
    setIsAtBottom(initialStickToBottom)
  }

  const {scrollToBottom} = useScrollToBottom({
    containerRef,
    behavior: scrollBehavior,
    smoothThreshold: 500,
  })

  // derive effective scrollable and content elements
  const getRootAndContent = useCallback(() => {
    const container = containerRef?.current
    if (!container) {
      const docEl = (document.scrollingElement || document.documentElement) as HTMLElement
      return {containerElement: null as HTMLElement | null, contentElement: docEl}
    }

    // prefer the sentinel's parent as content or fallback to the container itself
    const contentElement = sentinelRef.current?.parentElement ?? container
    return {containerElement: container, contentElement}
  }, [containerRef, sentinelRef])

  // Set up scroll listener — re-attaches when resetKey changes since it uses {once: true}.
  // Also resets ref-based state here (refs can't be accessed during render).
  useEffect(() => {
    hasScrolledRef.current = false
    isAtBottomRef.current = initialStickToBottom

    const container = containerRef?.current
    const scrollElement = container || window

    const handleScroll = () => {
      hasScrolledRef.current = true
    }

    // eslint-disable-next-line github/prefer-observers
    scrollElement.addEventListener('scroll', handleScroll, {once: true})

    return () => {
      scrollElement.removeEventListener('scroll', handleScroll)
    }
  }, [containerRef, resetKey, initialStickToBottom])

  // IntersectionObserver: check if user is (near) bottom
  useEffect(() => {
    const sentinel = sentinelRef.current
    if (!sentinel) return

    const {containerElement} = getRootAndContent()

    const io = new IntersectionObserver(
      entries => {
        const entry = entries[0]
        if (entry) {
          setIsAtBottom(entry.isIntersecting)
        }
      },
      {
        root: containerElement ?? null,
        rootMargin: `0px 0px ${offset}px 0px`,
        threshold: 0,
      },
    )

    io.observe(sentinel)
    return () => io.disconnect()
  }, [offset, getRootAndContent, sentinelRef])

  // ResizeObserver: keep sticking when content grows
  useEffect(() => {
    const {contentElement} = getRootAndContent()
    if (!contentElement) return

    const ro = new ResizeObserver(() => {
      // Auto-scroll if the user hasn't scrolled yet and initial stick is enabled,
      // or if the user has scrolled and is currently at bottom.
      if ((!hasScrolledRef.current && initialStickToBottom) || (hasScrolledRef.current && isAtBottomRef.current)) {
        scrollToBottom()
      }
    })

    ro.observe(contentElement)
    return () => ro.disconnect()
  }, [getRootAndContent, scrollToBottom, initialStickToBottom])

  return {
    isAtBottom,
    // waiting for a state to update is too late because ResizeObserver event is fired before that
    // so updating the ref directly
    setIsAtBottom: useCallback(
      (value: boolean) => {
        isAtBottomRef.current = value
        setIsAtBottom(value)
      },
      [setIsAtBottom],
    ),
  } as const
}
